def rank_svg(level,x=0,y=0,scale=1):
    level=max(0,min(len(RANKS)-1,int(level)))
    art=_ART[RANKS[level]['id']]
    return f'<g transform="translate({float(x):.2f} {float(y):.2f}) scale({float(scale):.4f})">{art}</g>'
def standalone(level):
    level=max(0,min(len(RANKS)-1,int(level)))
    label=RANKS[level]['label']
    svg=f'<svg xmlns="http://www.w3.org/2000/svg" width="180" height="190" viewBox="0 0 180 190" role="img" aria-label="AXR {label}">' + _ART[RANKS[level]['id']] + '</svg>\n'
    ET.fromstring(svg)
    return svg
